-- Seed content ideas for BowlSense content pipeline
-- Run: cd /home/mkerns/bowling-tracker/backend && sqlite3 bowling.db < scripts/seed-content-ideas.sql

INSERT OR REPLACE INTO content_ideas (id, title, description, status, platform, content_type, priority, labels, created_at, updated_at) VALUES
('ci001', 'Why Your Thumb Hole Is Lying to You', '## Hook\nHold ball to camera, thumb stuck halfway in.\n\n## What to say\n"Your thumb fit is wrong. And it''s why you can''t release the ball cleanly."\n\n## The test\nStick your thumb in your ball and let it hang at your side. If the ball stays on your thumb — you have a problem. The ball should fall off on its own.\n\n## Why it works\nMost bowlers grip too tight because the hole is too big. So they death-grip through the swing. Thumb goes in, ball hangs freely, thumb exits clean. No gripping. The fingers do the work.\n\n## CTA\n"Save this for before your next practice. Did your ball pass the test?"', 'idea', 'tiktok', 'short_form', 'high', 'tip,fix,thumb', datetime('now'), datetime('now')),
('ci002', '1-Hand vs 2-Hand: Same Lane, Same Ball', '## Concept\nSplit-screen: you bowling the same exact shot, two ways. Same ball. Same target. Same result?\n\n## Why it works\nVisual comparison content crushes on algorithm. "Which style wins?" triggers comments. No voiceover needed — let the ball do the talking.\n\n## Filming tip\nUse a side-by-side layout. Show the release in slow-mo for both. Let the pin action be the punchline.\n\n## Caption hook\n"1-hand or 2-hand: same lane, same ball, different physics."', 'idea', 'tiktok', 'short_form', 'high', 'comparison,1h,2h', datetime('now'), datetime('now')),
('ci003', 'Ball Speed Is Killing Your Hook', '## Hook\nTwo balls side by side. "Same ball. Same target. Different speed. Watch what happens."\n\n## Script outline\n- Throw 1: Crank it down fast. Ball rolls out, weak hit.\n- Throw 2: Same target, 2 mph slower. Ball picks up the corner hard, big strike.\n- Insight: "The slower ball had more time to read the friction on the back end. The hook is already in the ball. You just have to let it happen."\n\n## Proof format builds authority\nCounterintuitive insight ("slow down to hook more") stops the scroll. Showing the proof makes believers.\n\n## CTA\n"Try dropping your speed 2 mph at practice. Then tell me what happened."', 'idea', 'instagram', 'short_form', 'high', 'insight,speed,physics', datetime('now'), datetime('now')),
('ci004', 'The 3-Step Spare System That Never Fails', '## Hook\n"You''re not missing spares because you''re unlucky. You''re missing because you have no system."\n\n## The 3 steps\n1. **Identify** where the pin is — left, right, or middle.\n2. **Move** your feet in the OPPOSITE direction of the pin.\n3. **Aim** at the arrows, NOT the pins. Pick a board and commit.\n\n## Plastic ball note\nHook is your enemy on single-pin spares. Straight line, same target, every time.\n\n## Why system content performs\n"System" implies a shortcut. Spare shooting is every bowler''s pain point. Saves and bookmarks go through the roof.\n\n## CTA\n"Try this at your next session. Drop your spare percentage in the comments."', 'idea', 'youtube', 'short_form', 'medium', 'system,spares,fix', datetime('now'), datetime('now')),
('ci005', 'The Reason You''re Missing 7-Pins', '## Hook\nShow a 7-pin standing alone. "The 7-pin is not random. It''s your ball path telling you exactly what''s wrong."\n\n## Three reasons (pick one or all three)\n1. **Entry too high** — head pin drives straight back instead of through the 5-pin into the 7.\n2. **Too fast** — pins deflect differently when the ball is flying. Slow down.\n3. **Not enough entry angle** — ball coming in flat from outside the pocket carries 7s way better.\n\n## Fix\nMove 2 boards right, slow down 1–2 mph. 7-pins aren''t random. They''re data.\n\n## Why this works\nHyper-specific problem = hyper-specific audience who NEEDS this. "THIS IS ME" comments incoming.', 'idea', 'tiktok', 'short_form', 'medium', 'troubleshooting,7pin,carry', datetime('now'), datetime('now')),
('ci006', 'POV: Switched to 2-Handed and This Happened', '## Format\nPOV cam strapped to your wrist. First-person release of a 2H shot. Strike sound + pin explosion.\n\n## Why POV works on TikTok\nImmersive format drops viewers into the experience. Dopamine hit = replay. Strike sound = visceral.\n\n## Hook line\n"You switched to 2-handed and this happened."\n\n## CTA\n"Follow for the full breakdown on my channel."', 'idea', 'tiktok', 'short_form', 'medium', 'pov,2h,strike', datetime('now'), datetime('now')),
('ci007', '300 Using Only 2-Hand Releases', '## Viral angle\nAchievement + legitimacy challenge. 2H vs "2H isn''t real bowling" crowd = share wars.\n\n## Hook setup\nOpen on the 10th frame, 2H delivery, pin action, 12th strike. Cold open. No intro. Let the result pull viewers back.\n\n## Retention structure\n- Frames 1–9: rapid cuts\n- Frame 10: slow down. Text countdown. "Frame 10... can he do it?"\n- Tension + payoff = high watch time.\n\n## Debate driver\nThe 2H vs 1H legitimacy debate in the comments is the actual growth engine here.', 'idea', 'instagram', 'viral_bet', 'high', 'achievement,300,2h', datetime('now'), datetime('now')),
('ci008', 'Teaching My Dad to Bowl 2-Handed in 1 Hour', '## Viral angle\nFamily + transformation = warm fuzzies + share bait. Before/after writes itself.\n\n## Hook\nOpen on Dad throwing a weak, low-rev 1H shot. Cut to 1 hour later: 2H delivery, clean strike.\n\n## Retention beats\n- 10 minutes in: first breakthrough\n- 30 minutes in: visible improvement\n- Final: Dad''s reaction to his first clean strike\n\n## Caption hook\n"I taught my dad to bowl 2-handed in one hour. Here''s exactly how we got there."', 'idea', 'youtube', 'viral_bet', 'medium', 'family,2h,transformation', datetime('now'), datetime('now')),
('ci009', 'How to Read Bowling Oil Patterns', '## Long-form outline (24 min)\n\n### Cold open [0:00]\nTwo shots, same ball, different hook points — no explanation yet.\n\n### What is oil? [0:45]\nOil = less friction = ball goes straight. Dry = more friction = ball hooks.\n\n### Three zones [2:30]\nHeads / midlane / backend — what each does to your ball on a house shot.\n\n### House vs sport [5:00]\nThe "wall" effect of house shots vs punishment for bad angles on sport patterns.\n\n### Reading breakdown [8:30]\nThree signs you need to move: over-hooking early, sliding through backend, going through the nose.\n\n### 2-board rule [12:00]\nProblem → move → fix. Real-time demo.\n\n### 1H vs 2H on patterns [19:00]\nHigher revs burn through oil faster. Honest comparison only you can give.\n\n## 3 title options\n1. "How to Read Bowling Oil Patterns (Finally Explained Simply)"\n2. "Why Your Ball Goes Where It Does: The Complete Oil Pattern Guide"\n3. "Oil Patterns Explained: The Bowling Secret Leagues Don''t Teach You"\n\n## Retention beats\n1. [2:00] "Most house shots funnel your ball to the pocket — you might be bowling well without actually being a good bowler."\n2. [8:30] "Three things your ball is telling you right now — most bowlers ignore all three."\n3. [19:00] "Same oil pattern, 1-handed AND 2-handed. Which style wins?"', 'idea', 'youtube', 'long_form', 'high', 'long-form,oil,patterns', datetime('now'), datetime('now')),
('ci010', '1H vs 2H: Year-Long Experiment', '## Angle\nYou can bowl both styles. That''s your unfair advantage — no one else can do this comparison honestly.\n\n## What to track\n- Carry percentage (1H vs 2H on same conditions)\n- Rev rate vs entry angle\n- Spare shooting consistency\n- Pattern adaptation speed\n\n## Script structure\n"This is the honest data from a year of bowling both styles on the same conditions. Not what the internet says — what the scorebook says."\n\n## Audience hook\n"I spent a year actually tracking the data. Here''s the truth about which style gives you a better shot at higher scores."\n\n## Unique differentiator\nNo other bowling creator can do this comparison from the inside. Use it.', 'idea', 'youtube', 'long_form', 'medium', 'long-form,1h,2h,data', datetime('now'), datetime('now'));
